import{z as A,x as B,o as r,c as d,q as n,j as o,D as E,d as l,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Grossman–Miller 流动性提供","description":"","frontmatter":{"title":"Grossman–Miller 流动性提供","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/grossman-miller.md","filePath":"quant/grossman-miller.md","lastUpdated":1791413859000}'),p={name:"quant/grossman-miller.md"};function m(u,a,C,h,M,c){const s=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="grossman–miller-流动性提供" tabindex="-1">Grossman–Miller 流动性提供 <a class="header-anchor" href="#grossman–miller-流动性提供" aria-label="Permalink to &quot;Grossman–Miller 流动性提供&quot;">​</a></h1><div class="epigraph"><p>流动性不是做市商的人格美德，而是有人愿意在冲击到达的那一期吸收存货、等到下一期再把风险交给更多人分担。提供流动性就是跨期的风险转移。</p><footer>—— Grossman and Miller, Liquidity and Market Structure, Journal of Finance, 1988</footer></div><p><a href="/quant/ho-stoll-inventory">Ho–Stoll</a>写出单个经销商如何给自己的库存定价。缺口是市场结构：为什么需要一群常设的流动性提供者，而不是让所有投资者等下一期再见面？Grossman 与 Miller（1988）把流动性定义成<strong>即时性的供给</strong>：外生需求冲击来的那一期，有人先接走存货；到了更多交易者到场的下一期，风险被重新分担，价格部分回复。本课不重做最优买卖价差的一阶条件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若所有人只能在同一期交易，需求冲击会立刻反映在价格里，没有「暂时」与「永久」之分。现实里交易者不同时在场：有人必须现在卖，有人要等新闻、等资金、等下一次拍卖。市场结构决定有多少风险承担者现在在场。人数少时，接住冲击的人要求很大的价格折让；下一期人到齐，折让消失，价格回复。问题是：均衡里有多少人选择成为常设的流动性提供者（持有做市能力、等待冲击），以及即时价格相对充分分担价格的偏离有多大。</p><p>这把「价差」从经销商的报价宽度，改写成<strong>两期价格路径</strong>上的暂时成分。它与信息范式正交：即使没有知情交易，只要人不同时在场，就会有冲击与回复。</p><p><span class="marginnote">直觉类比：深夜打车的溢价。白天司机多（第 2 期人人到场），价格接近正常；深夜只剩两三辆车（第 1 期少数人在场），急着走的人得多付一笔——这笔溢价不是司机贪心，也不是车变贵了，只是「此刻在场、愿意接单」的人少。下一早高峰，价格自然回落。即时性本身就是商品。</span></p><h3 id="做市商人数是均衡对象" tabindex="-1">做市商人数是均衡对象 <a class="header-anchor" href="#做市商人数是均衡对象" aria-label="Permalink to &quot;做市商人数是均衡对象&quot;">​</a></h3><p>成为流动性提供者有成本（资本、注意力、库存风险）。人数 \\(M\\) 增加，每一期冲击被更多人分担，即时折让变小，做市利润下降，直到与进入成本抵平。\\(M\\) 太少则折让巨大、做市租高，会吸引进入。市场「有多流动」因此是内生的，不是外生的 \\(\\sigma_u\\)。</p><p><span class="marginnote">Kyle 的噪声交易者提供掩护但不优化；Grossman–Miller 的流动性需求者有外生时机，流动性供给者优化是否在场。噪声规模在这里部分内生化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期（或有限多期）均值–方差交易者。第 1 期一小群人在场，出现外生供给冲击 \\(z\\)；第 2 期全体到场，价值公开或风险被充分分担。第 1 期出清价 \\(p_1\\) 相对第 2 期期望价格的折让，补偿在场者暂时持有 \\(z\\)。折让与 \\(z\\)、风险厌恶、在场人数成比例——形式上像一个库存压力价格，但压力来自<strong>谁在场</strong>，不是某一个专家的 \\(I\\)。</p><p>进入均衡：\\(M\\) 个做市商预先支付成本，换取第 1 期在场的权利。期望做市利润随 \\(M\\) 下降。比较静态：冲击更频繁或更大、资产波动更高，均衡 \\(M\\) 增加，但即时折让不必单调——进入与风险对冲。</p><h3 id="暂时价格与可预测回复" tabindex="-1">暂时价格与可预测回复 <a class="header-anchor" href="#暂时价格与可预测回复" aria-label="Permalink to &quot;暂时价格与可预测回复&quot;">​</a></h3><p>第 1 期被压低（抬高）的价格，在第 2 期期望回复。收益因此出现负的序列相关，来源是存货的跨期分担，不是 Roll 的买卖弹跳，也不是反应不足。经验上要把「暂时成分」从信息引起的永久成分里分开，需要后文 Hasbrouck 的结构；本课只给出一种纯粹的暂时成分机制。</p>',15)),(r(),o(i,null,{default:E(()=>[t(s,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20Z%5B%22%E7%AC%AC1%E6%9C%9F%E4%BE%9B%E7%BB%99%E5%86%B2%E5%87%BB%20z%22%5D%20--%3E%20P1%5B%22%E5%B0%91%E6%95%B0%E5%9C%A8%E5%9C%BA%E8%80%85%E5%87%BA%E6%B8%85%20p1%22%5D%0A%20%20P1%20--%3E%20Inv%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E6%8C%81%E6%9C%89%E5%AD%98%E8%B4%A7%22%5D%0A%20%20Inv%20--%3E%20P2%5B%22%E7%AC%AC2%E6%9C%9F%E5%85%85%E5%88%86%E5%88%86%E6%8B%85%20p2%22%5D%0A%20%20P2%20-.-%3E%7C%22%E6%9C%9F%E6%9C%9B%E5%9B%9E%E5%A4%8D%22%7C%20P1%0A%20%20M%5B%22%E5%9D%87%E8%A1%A1%E5%81%9A%E5%B8%82%E4%BA%BA%E6%95%B0%20M%22%5D%20--%3E%20P1%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"即时性是一种商品。需求方为了现在成交，接受不利价格；供给方用资本换取这笔风险溢价。市场设计改变的是第 1 期有多少人在场：连续交易、指定做市商、强制做市义务，都是在改变 \\(M\\) 与在场约束。电子限价簿把「在场」改成挂单——你不必是注册经销商，但你的限价单同样是在某一瞬间提供即时性。",-1)),a[5]||(a[5]=e("p",null,"危机里 \\(M\\) 有效下降（资本约束、撤退），同样大小的 \\(z\\) 造成更大折让，看起来像流动性蒸发。Brunnermeier–Pedersen 的融资流动性会把这条线接到资金约束；本课的机制已经足够：在场风险分担能力收缩，暂时折让放大。",-1)),(r(),o(i,null,{default:E(()=>[t(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%9B%BA%E5%AE%9A%E5%A4%A7%E5%B0%8F%E5%86%B2%E5%87%BB%20z%22%5D%20--%3E%20M%7B%22%E7%AC%AC1%E6%9C%9F%E5%9C%A8%E5%9C%BA%E4%BA%BA%E6%95%B0%20M%22%7D%0A%20%20M%20--%3E%7C%22M%20%E5%A4%A7%3A%20%E9%A3%8E%E9%99%A9%E4%BC%97%E4%BA%BA%E5%88%86%22%7C%20SMALL%5B%22%E6%8A%98%E8%AE%A9%E5%B0%8F%3A%20p1%20%E6%8E%A5%E8%BF%91%20p2%22%5D%0A%20%20M%20--%3E%7C%22M%20%E5%B0%8F%3A%20%E5%B0%91%E6%95%B0%E4%BA%BA%E6%89%9B%22%7C%20BIG%5B%22%E6%8A%98%E8%AE%A9%E5%A4%A7%3A%20p1%20%E5%A4%A7%E5%B9%85%E4%BD%8E%E4%BA%8E%20p2%22%5D%0A%20%20SMALL%20--%3E%20PROFT%5B%22%E4%BA%BA%E5%9D%87%E5%81%9A%E5%B8%82%E5%88%A9%E6%B6%A6%E4%BD%8E%22%5D%0A%20%20BIG%20--%3E%20PROFT2%5B%22%E4%BA%BA%E5%9D%87%E5%81%9A%E5%B8%82%E5%88%A9%E6%B6%A6%E9%AB%98%22%5D%0A%20%20PROFT2%20--%3E%20ENTER%5B%22%E5%90%B8%E5%BC%95%E6%96%B0%E5%81%9A%E5%B8%82%E5%95%86%E8%BF%9B%E5%85%A5%22%5D%0A%20%20ENTER%20--%3E%7C%22M%20%E5%9B%9E%E5%8D%87%22%7C%20M%0A%20%20CRISIS%5B%22%E5%8D%B1%E6%9C%BA%3A%20%E8%B5%84%E6%9C%AC%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%7C%22M%20%E8%A2%AB%E5%8A%A8%E6%94%B6%E7%BC%A9%22%7C%20BIG%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两期、对称信息、外生冲击，不解释逆向选择导致的永久性价格移动。真实冲击里夹着知情交易，\\(p_1\\) 的折让部分永不回复。Grossman–Miller 也不能单独给出买卖价差的买卖两侧：它给出的是交易价格相对充分信息价格的压力。要把压力写成 bid/ask，需回到 Ho–Stoll 或限价簿模型。</p><p><span class="marginnote">不要把「价格回复」自动当成 Grossman–Miller 成功。过度反应、集合竞价收盘、指数再平衡都可以制造回复。识别需要看到存货或做市商资本，而不只是自相关符号。</span></p><p><span class="marginnote">数字实例：假设冲击要移交 100 万股存货给在场者。若第 1 期有 20 家做市商在场，每家扛 5 万股，要求的补偿折让是每股 0.2 元；若危机后只剩 4 家在场，每家要扛 25 万股，风险敞口扩大 5 倍，折让可能放大到 1 元以上——同样的冲击，「在场人数」就是把暂时价格波动放大数倍的旋钮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Grossman–Miller（1988）把流动性定义为跨期风险分担：少数人先接冲击，全体到场后价格回复。</li><li>做市商人数是均衡对象，由做市利润与进入成本决定。</li><li>暂时折让可以完全来自不同时在场，不必有知情者。</li><li>与 Ho–Stoll 的个体库存优化互补：一个问谁在场，一个问在场者如何报价。</li><li>出处：Grossman and Miller, <em>Journal of Finance</em>, 1988；库存报价见 Ho and Stoll, 1981。</li></ul>',6))])}const _=A(p,[["render",m]]);export{f as __pageData,_ as default};
